using System.Collections.Generic;
using RimWorld;
using Verse;

namespace TorannMagic
{
    // Ф5: grants vanilla bridge abilities from the knowledge store. Bridges for
    // the whole ability tree exist as dormant defs (generated by
    // scripts/generate-ability-bridges.py); only families that passed their
    // live acceptance are enabled here, so no pawn sees double gizmos for a
    // family still on the classic path. Idempotent per pawn.
    public static class VanillaBridgeSync
    {
        // Rollout gate: spellId prefixes enabled in the vanilla tracker.
        // "rwom.tm_heal" = the Heal pilot family.
        private static readonly string[] EnabledFamilyPrefixes = { "rwom.tm_heal" };

        private static readonly Dictionary<string, TMBridgeAbilityDef> BridgeDefs =
            new Dictionary<string, TMBridgeAbilityDef>();

        public static void Sync(Pawn pawn)
        {
            if (pawn?.abilities == null) return;
            AbilityKnowledgeComp knowledge = pawn.TryGetComp<AbilityKnowledgeComp>();
            if (knowledge == null) return;
            foreach (SpellKnowledge entry in knowledge.Spells)
            {
                if (entry == null || !entry.learned || string.IsNullOrEmpty(entry.spellId)) continue;
                if (!FamilyEnabled(entry.spellId)) continue;
                TMBridgeAbilityDef bridge = BridgeDef(entry.spellId);
                if (bridge == null) continue;
                if (pawn.abilities.GetAbility(bridge) != null) continue;
                pawn.abilities.GainAbility(bridge);
            }
        }

        // Prefix match with a defName boundary: "rwom.tm_heal" must not swallow
        // "rwom.tm_healingcircle".
        private static bool FamilyEnabled(string spellId)
        {
            foreach (string prefix in EnabledFamilyPrefixes)
            {
                if (!spellId.StartsWith(prefix)) continue;
                if (spellId.Length == prefix.Length || spellId[prefix.Length] == '_') return true;
            }
            return false;
        }

        private static TMBridgeAbilityDef BridgeDef(string spellId)
        {
            if (BridgeDefs.TryGetValue(spellId, out TMBridgeAbilityDef cached))
            {
                return cached;
            }
            // Bridge defName convention: rwom.tm_heal -> TM_Bridge_Heal.
            string name = GrimoireKnowledge.DisplayName(spellId)?.Replace(" ", "") ?? null;
            TMBridgeAbilityDef def = name == null
                ? null
                : DefDatabase<AbilityDef>.GetNamedSilentFail("TM_Bridge_" + name) as TMBridgeAbilityDef;
            if (def != null)
            {
                BridgeDefs[spellId] = def; // do not cache misses: defs may register later
            }
            return def;
        }
    }
}
